  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Michel Della Negra",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The experimental discovery of the Higgs boson completed a central test of the Standard Model and demonstrated an extraordinary capacity to build and operate experiments at unprecedented scale.",
        "attribution": "The proposed recognition appropriately focuses on leaders of ATLAS and CMS, while the discovery depended on thousands of contributors and a worldwide accelerator effort. Credit among experimental leaders requires careful historical assessment.",
        "maturity": "The particle's properties have been measured across many decay channels, with results broadly consistent with the Higgs boson predicted by the Standard Model.",
        "uncertainties": [
          "The award would need to recognize experimental discovery without implying that the proposed individuals alone built or analyzed the experiments."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov–Bohm effect and Berry phase reveal that quantum phases have observable consequences and connect geometry to physical phenomena across many areas of physics.",
        "attribution": "Aharonov's effect and Berry's phase are distinct contributions with different histories; both names are strongly associated with the concepts grouped here, though the candidate combines them into a broad theme.",
        "maturity": "These ideas have been experimentally verified and have become standard tools in quantum mechanics and condensed matter physics.",
        "uncertainties": [
          "The breadth of the proposed discovery makes the boundaries of the contribution and the appropriate scope of recognition less clear."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precise mapping of cosmic microwave background anisotropies transformed cosmology into a precision science and established a quantitative framework for the universe's composition and evolution.",
        "attribution": "The proposed names represent major scientific and leadership contributions, but the result was produced by a large collaboration; a defensible account must distinguish instrument, analysis, and interpretation contributions.",
        "maturity": "The measurements have been independently refined by later experiments and remain a durable foundation for cosmological inference.",
        "uncertainties": [
          "Some cosmological parameters remain in tension across measurement methods, though this does not erase WMAP's foundational role."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and realization of time-reversal-invariant topological insulators and the quantum spin Hall effect opened a major field and showed how topology can govern electronic states in real materials.",
        "attribution": "Kane and Mele provided central theoretical work, while Molenkamp's experiments demonstrated the quantum spin Hall effect. The larger development involved other theorists and experimental groups as well.",
        "maturity": "The underlying phenomena have been established experimentally, and topological band concepts now organize a broad body of condensed matter research.",
        "uncertainties": [
          "The proposed discovery covers a field that developed through several predictions, materials, and experimental milestones."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "AdS/CFT is a remarkable conceptual bridge between gravity and quantum field theory, with major influence on quantum gravity and strongly coupled systems.",
        "attribution": "Maldacena's duality conjecture is the defining contribution; Witten developed and clarified its structure. Polyakov's earlier work is important background, but the proposed pair most directly represents the correspondence as formulated.",
        "maturity": "The duality has been extensively tested mathematically and has proved useful, but its connection to the observed universe and direct experimental confirmation remain open.",
        "uncertainties": [
          "It remains uncertain whether the correspondence describes nature or is a powerful mathematical relation restricted to special theoretical settings."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals established the ability to control light through engineered periodic structures, creating a durable conceptual and practical foundation for modern photonics.",
        "attribution": "Yablonovitch and John independently articulated influential routes to photonic band gaps; Joannopoulos made major theoretical contributions. The history includes parallel work and subsequent community development.",
        "maturity": "The band-structure principles are well established and underpin a wide range of optical devices and research.",
        "uncertainties": [
          "A prize would need to distinguish the original insight from later advances that made photonic crystals broadly useful."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault tolerance showed how quantum information can in principle be protected against noise, changing the question of whether scalable quantum computation is physically possible.",
        "attribution": "Shor and Steane developed pivotal early codes, while Kitaev's topological approach made a distinct foundational contribution. The candidate groups several related advances whose histories and emphases differ.",
        "maturity": "The theory is robust and experimental control has advanced considerably, but large-scale fault-tolerant quantum computation has not yet been demonstrated.",
        "uncertainties": [
          "The ultimate practical reach of fault-tolerant quantum computing remains unsettled.",
          "The broad scope of the candidate makes it difficult to identify one discovery boundary."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions have enabled precise control of individual quantum systems and provided a leading platform for quantum simulation and computation.",
        "attribution": "Cirac and Zoller formulated influential proposals for ion-based quantum computation, while Blatt's experiments helped establish controllable entangling operations. The platform's development has involved many groups.",
        "maturity": "Ion trapping and quantum control are highly mature, with increasingly capable demonstrations, though large-scale fault-tolerant computation remains a goal.",
        "uncertainties": [
          "The proposed contribution spans a platform and several decades of progress, so the prize-worthy discovery needs a more precise definition."
        ]
      }
    }
  ]
}
